            <span class="text-sm text-slate-500">Built over the Umbraco MCP server</span>
        </div>
    </header>

    <main class="mx-auto w-full max-w-5xl flex-1 px-4 py-8 sm:px-6 sm:py-10">
        @RenderBody()
    </main>

    <footer class="border-t border-slate-200 bg-white">
        <div class="mx-auto max-w-5xl px-4 py-6 text-sm text-slate-500 sm:px-6">
            &copy; @DateTime.Now.Year @siteName. Images from Unsplash.
        </div>
    </footer>

    <script type="module" src="~/dist/main.js" asp-append-version="true"></script>
</body>
</html>
