/* Block grid: Umbraco's partials emit the column and row spans as custom properties. */
.umb-block-grid__layout-container,
.umb-block-grid__area-container {
    display: grid;
    grid-template-columns: repeat(var(--umb-block-grid--grid-columns, 12), minmax(0, 1fr));
    gap: 2.5rem 2rem;
}

.umb-block-grid__area-container {
    grid-template-columns: repeat(var(--umb-block-grid--area-grid-columns, 12), minmax(0, 1fr));
}

.umb-block-grid__layout-item {
    grid-column-end: span var(--umb-block-grid--grid-columns, 12);
    grid-row-end: span var(--umb-block-grid--item-row-span, 1);
}

.umb-block-grid__area {
    grid-column-end: span var(--umb-block-grid--area-grid-columns, 12);
    grid-row-end: span var(--umb-block-grid--area-row-span, 1);
}

@media (min-width: 48rem) {
    .umb-block-grid__layout-item {
        grid-column-end: span var(--umb-block-grid--item-column-span, 12);
    }

    .umb-block-grid__area {
        grid-column-end: span var(--umb-block-grid--area-column-span, 12);
    }
}

/* Editor-authored markup from the rich text editor. */
.rich-text {
    @apply text-lg leading-relaxed text-slate-700;
}

.rich-text > :first-child {
    @apply mt-0;
}

.rich-text h2 {
    @apply mt-10 mb-3 text-2xl font-semibold tracking-tight text-slate-900;
}

.rich-text h3 {
    @apply mt-8 mb-2 text-xl font-semibold text-slate-900;
}

.rich-text p {
    @apply my-4;
}

.rich-text ul {
    @apply my-4 list-disc space-y-2 pl-6;
}

.rich-text ol {
    @apply my-4 list-decimal space-y-2 pl-6;
}

.rich-text strong {
    @apply font-semibold text-slate-900;
}

.rich-text a {
    @apply text-indigo-600 underline hover:text-indigo-800;
}

.rich-text code {
    @apply rounded bg-slate-200 px-1.5 py-0.5 font-mono text-sm text-slate-900;
}

